{
  "description": "The creature is shown in left-facing side profile against a plain light background, standing as a single quadrupedal animal. It has the overall body, head, legs and tail of a shaggy brown goat with a large, domed tortoise shell covering its back from just behind the shoulders to the rump. The coat is long, coarse and wavy, dark to medium brown on the neck, back and legs with a lighter cream underbelly, and a tufted beard under the chin. Two curved horns sit on top of the head, and a short fluffy tail sticks out from beneath the rear edge of the shell. All four legs end in cloven hooves and the animal is depicted mid-stance as if walking.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat-like head at the far left front of the body in profile facing left, with a narrow muzzle, dark nostril, closed mouth, a visible dark eye with eyelid, short brown fur on the face and a tufted beard hanging from the chin",
      "where": "frontmost left end of the body"
    },
    {
      "part": "horns",
      "looks_like": "two thick, ridged, brown horns with growth rings curving backward and slightly outward, the nearer horn in front overlapping the farther horn",
      "where": "on top of the head behind the forehead, above the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, pointed, furry ears with visible inner ear detail, brown on the outside and lighter inside",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "long, shaggy, coarse brown fur forming a thick mane around the neck and chest and covering the entire body and upper legs, wavy texture, darker brown dorsally and cream-white on the belly",
      "where": "around the neck, chest, torso, and covering the legs"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, straight, fur-covered legs, brown and shaggy, with slight joint definition",
      "where": "two forelegs under the chest and two hindlegs under the rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four cloven hooves, dark brown to black keratin with two toes each, partially covered by fur at the top",
      "where": "at the bottom tip of each leg on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, fluffy, brown tail with long hair, bushy at the tip",
      "where": "at the extreme rear right of the body, protruding from under the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "a large, domed, hard carapace with raised pyramidal scutes, brown with dark brown and tan concentric growth lines and geometric segmentation, each central scute peaked, with a scalloped lower edge",
      "where": "covering the dorsal mid-back from behind the shoulders to above the hindquarters, sitting on top of the fur"
    }
  ],
  "attached_objects": [],
  "animals": ["goat", "tortoise"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
